import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def helps(payload):
    return [item.get('help') for item in payload['items']]

inferred_local = verify('inferred_local', '''
    fn borrow(v: &'a i32) -> &'a i32 {
        return v
    }
    async fn worker(v: &'a i32) -> i32 {
        let alias = borrow(v)
        await recv()
        discard alias
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('cannot use borrowed local reference `alias` across await suspension points' in message for message in messages(inferred_local)), inferred_local
assert any(help == 'resolve the borrowed local before `await`, or keep only owned data alive across the suspension point' for help in helps(inferred_local)), inferred_local

if_body = verify('if_body', '''
    async fn worker(v: &'a i32) -> i32 {
        if true {
            await recv()
            discard v
        }
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('cannot use borrowed reference `v` across await suspension points' in message for message in messages(if_body)), if_body
assert any(help == 'move the `await` before the borrowed use, or replace the borrowed path with an owned value across suspension' for help in helps(if_body)), if_body

match_arm = verify('match_arm', '''
    async fn worker(v: &'a i32) -> i32 {
        match await recv() {
            0 => v,
            _ => 0,
        }
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('cannot use borrowed reference `v` across await suspension points' in message for message in messages(match_arm)), match_arm
assert any(help == 'move the `await` before the borrowed use, or replace the borrowed path with an owned value across suspension' for help in helps(match_arm)), match_arm

loop_body = verify('loop_body', '''
    async fn worker(v: &'a i32) -> i32 {
        while false {
            await recv()
            discard v
        }
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('cannot use borrowed reference `v` across await suspension points' in message for message in messages(loop_body)), loop_body
assert any(help == 'move the `await` before the borrowed use, or replace the borrowed path with an owned value across suspension' for help in helps(loop_body)), loop_body

print('compiler-memory-same-function-await-refs-ok')

